/* Plain JavaScript. Demo changes stay in this tab; live mode uses the Python API. */
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP',maximumFractionDigits:2}).format((n||0)/100);
const peso=n=>Math.round(Number(n)*100);
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const dateLabel=d=>d?new Date(d+'T12:00:00').toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric'}):'—';
const shortDate=d=>d?new Date(d+'T12:00:00').toLocaleDateString('en-PH',{month:'short',day:'numeric'}):'—';
const nextDue=(start,index=1)=>{const d=new Date(start+'T12:00:00'),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+index);const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,last));return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const houseSvg='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4"><path d="M3 11 12 3l9 8M5 9.5V21h14V9.5M9 21v-7h6v7"/></svg>';
function freshState(){return {version:0,settings:{electricRate:2500,waterRate:7000,name:'Paupahan Manager',address:'Rental property'},houses:Array.from({length:10},(_,i)=>({id:'H'+String(i+1).padStart(2,'0'),label:'House '+String(i+1).padStart(2,'0'),rent:400000+(i%3)*50000,tenantId:null})),tenants:[],bills:[],payments:[],audit:[]}}
function sampleState(){const s=freshState(),now=today(),year=Number(now.slice(0,4)),month=Number(now.slice(5,7)),names=['Maria Santos','Jose Dela Cruz','Ana Reyes','Carlo Mendoza','Liza Garcia','Ramon Flores','Elena Bautista','Paolo Ramos'];names.forEach((name,i)=>{const move=[year,String(month).padStart(2,'0'),String([5,8,13,16,20,22,25,28][i]).padStart(2,'0')].join('-'),t={id:'T'+(i+1),houseId:s.houses[i].id,name,contact:'09•• ••• ••••',moveIn:nextDue(move,-6),deposit:s.houses[i].rent,advance:s.houses[i].rent,advancePolicy:'unconfirmed',credit:0,documents:[],archived:false};s.tenants.push(t);s.houses[i].tenantId=t.id;const b={id:'B'+(i+1),tenantId:t.id,houseId:t.houseId,period:now.slice(0,7),due:move,rent:s.houses[i].rent,electric:100000+(i%4)*25000,water:28000,other:0,electricRate:2500,waterRate:7000,readings:{electricPrevious:1200+i*100,electricCurrent:1240+i*100+(i%4)*10,waterPrevious:80+i*10,waterCurrent:84+i*10},paid:0,mode:'meter',notes:''};s.bills.push(b);if(i===1||i===5||i===7){const amount=b.rent+b.electric+b.water;b.paid=amount;s.payments.push({id:'sample-'+i,receipt:'PM-'+year+'-000'+(i+1),tenantId:t.id,houseId:t.houseId,tenantName:name,houseLabel:s.houses[i].label,amount,date:now,recordedAt:new Date().toISOString(),recordedBy:'Mom',allocations:[{billId:b.id,amount}],credit:0,voided:false})}if(i===0){b.paid=200000;s.payments.push({id:'sample-partial',receipt:'PM-'+year+'-0001',tenantId:t.id,houseId:t.houseId,tenantName:name,houseLabel:s.houses[i].label,amount:200000,date:now,recordedAt:new Date().toISOString(),recordedBy:'Mom',allocations:[{billId:b.id,amount:200000}],credit:0,voided:false})}});return s}
let state=sampleState(),user={name:'Owner',role:'owner'},demo=true,liveAvailable=false,config={},filter='all',query='',reportMonth=today().slice(0,7),lastPayment=null;
const activeTenant=h=>state.tenants.find(t=>t.id===h.tenantId&&!t.archived);
const tenantBills=t=>state.bills.filter(b=>b.tenantId===t.id).sort((a,b)=>a.due.localeCompare(b.due)||a.id.localeCompare(b.id));
const billTotal=b=>b.rent+b.electric+b.water+b.other;
const tenantBalance=t=>tenantBills(t).reduce((n,b)=>n+billTotal(b)-b.paid,0);
function status(h){const t=activeTenant(h);if(!t)return {key:'vacant',label:'Vacant'};const bills=tenantBills(t),pending=bills.filter(b=>billTotal(b)>b.paid);if(!bills.length)return {key:'due',label:'No bill yet'};if(!pending.length)return {key:'paid',label:'Paid'};if(pending.some(b=>b.due<today()))return {key:'overdue',label:'Overdue'};if(pending.some(b=>b.paid>0))return {key:'partial',label:'Partial'};return {key:'due',label:'Due soon'}}
const badge=s=>'<span class="badge '+s.key+'">'+esc(s.label)+'</span>';
const button=(text,action,id='',kind='')=>'<button type="button" class="btn '+kind+'" data-action="'+action+'" data-id="'+esc(id)+'">'+text+'</button>';
const field=(label,name,type='text',value='',extra='',help='')=>'<div class="field"><label for="f-'+name+'">'+label+'</label><input id="f-'+name+'" name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+extra+'>'+ (help?'<small>'+help+'</small>':'')+'</div>';
const cashField=(label,name,value=0,help='')=>field(label,name,'number',value/100,'min="0" step="0.01" required',help);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function modal(title,subtitle,body,submitLabel,onSubmit){$('#modal-heading').innerHTML='<h2>'+esc(title)+'</h2><p>'+esc(subtitle)+'</p>';$('#modal-body').innerHTML=body+'<div class="form-error" id="form-error" role="alert"></div>';$('#modal-actions').innerHTML='<button type="button" class="btn" id="cancel-modal">Cancel</button>'+(submitLabel?'<button class="btn primary" type="submit">'+esc(submitLabel)+'</button>':'');$('#cancel-modal').onclick=()=>$('#modal').close();$('#modal-form').onsubmit=async e=>{e.preventDefault();const submit=e.submitter;if(submit)submit.disabled=true;try{await onSubmit(new FormData(e.target));$('#modal').close()}catch(err){$('#form-error').textContent=err.message}finally{if(submit)submit.disabled=false}};$('#modal').showModal()}
$('#close-modal').onclick=()=>$('#modal').close();
function ownerOnly(){if(user.role!=='owner')throw new Error('Only the owner can change this record.')}
function requireNumber(v,min=0){const n=Number(v);if(!Number.isFinite(n)||n<min)throw new Error('Enter a valid amount.');return n}
function applyDemo(action,p){if(user.role==='viewer')throw new Error('Viewer access cannot save records.');if(action!=='payment')ownerOnly();const before=structuredClone(state);try{const h=state.houses.find(h=>h.id===p.houseId),t=h&&activeTenant(h);if(action==='house'){if(state.houses.some(h=>h.label.toLowerCase()===p.label.toLowerCase()))throw new Error('That house name already exists.');state.houses.push({id:crypto.randomUUID(),label:p.label,rent:p.rent,tenantId:null})}
else if(action==='tenant'){if(!h||t)throw new Error('Choose a vacant house.');const tenant={...p,id:crypto.randomUUID(),credit:0,archived:false,documents:[]};state.tenants.push(tenant);h.tenantId=tenant.id}
else if(action==='bill'){if(!t)throw new Error('Assign a tenant first.');if(tenantBills(t).some(b=>b.period===p.period))throw new Error('A bill for this month already exists.');if(p.due<t.moveIn)throw new Error('The due date cannot be before move-in.');let readings=p.readings||{};if(p.mode==='meter'){if(readings.electricCurrent<readings.electricPrevious||readings.waterCurrent<readings.waterPrevious)throw new Error('Present readings cannot be below previous readings.');p.electric=Math.round((readings.electricCurrent-readings.electricPrevious)*state.settings.electricRate);p.water=Math.round((readings.waterCurrent-readings.waterPrevious)*state.settings.waterRate)}const b={...p,id:crypto.randomUUID(),tenantId:t.id,electricRate:state.settings.electricRate,waterRate:state.settings.waterRate,paid:0};state.bills.push(b);if(t.credit>0){const use=Math.min(t.credit,billTotal(b));b.paid+=use;t.credit-=use;state.audit.push({action:'credit_applied',date:new Date().toISOString(),by:user.name,billId:b.id,amount:use})}}
else if(action==='payment'){if(!t)throw new Error('No active tenant.');if(p.amount<=0)throw new Error('The amount received must be more than zero.');if(state.payments.some(x=>x.id===p.requestId))return;let remaining=p.amount,allocations=[];tenantBills(t).forEach(b=>{const use=Math.min(remaining,billTotal(b)-b.paid);if(use>0){b.paid+=use;remaining-=use;allocations.push({billId:b.id,amount:use,billSnapshot:structuredClone(b)})}});t.credit+=remaining;const payment={id:p.requestId,receipt:'PM-'+p.date.slice(0,4)+'-'+String(state.payments.length+1).padStart(5,'0'),tenantId:t.id,houseId:h.id,tenantName:t.name,houseLabel:h.label,amount:p.amount,date:p.date,notes:p.notes||'',recordedAt:new Date().toISOString(),recordedBy:user.name,allocations,credit:remaining,balanceAfter:tenantBalance(t),voided:false};state.payments.push(payment);lastPayment=payment}
else if(action==='bill_correction'){const b=state.bills.find(b=>b.id===p.billId);if(!b||!p.reason?.trim())throw new Error('Provide a correction reason.');const prior=structuredClone(b);const correction={rent:p.rent,electric:p.electric||0,water:p.water||0,other:p.other||0,mode:p.mode,readings:p.readings||{},notes:p.notes||''};if(p.mode==='meter'){for(const kind of ['electric','water']){const r=p.readings;if(r[kind+'Current']<r[kind+'Previous'])throw new Error('Present reading cannot be below previous reading.');correction[kind]=Math.round((r[kind+'Current']-r[kind+'Previous'])*b[kind+'Rate'])}}if(billTotal(correction)<b.paid)throw new Error('Corrected total cannot be below payments already applied.');state.audit.push({action:'bill_previous_version',date:new Date().toISOString(),by:user.name,reason:p.reason,bill:prior});Object.assign(b,correction)}
else if(action==='rates'){state.settings.electricRate=p.electricRate;state.settings.waterRate=p.waterRate;if(h)h.rent=p.rent}
else if(action==='settings'){Object.assign(state.settings,p)}
else if(action==='void'){const pay=state.payments.find(x=>x.id===p.paymentId);if(!pay||pay.voided)throw new Error('This payment has already been voided.');if(!p.reason?.trim())throw new Error('A correction reason is required.');const tenant=state.tenants.find(t=>t.id===pay.tenantId);if(tenant.archived||pay.credit>tenant.credit)throw new Error('Advance credit has already been used; review the ledger before reversing this payment.');pay.allocations.forEach(a=>{state.bills.find(b=>b.id===a.billId).paid-=a.amount});tenant.credit-=pay.credit;pay.voided=true;pay.voidReason=p.reason}
else if(action==='archive'){if(!t)throw new Error('No active tenant.');if(!p.checklist)throw new Error('Complete the settlement review first.');t.archived=true;t.moveOut=p.date;t.settlement={outstanding:tenantBalance(t),deposit:t.deposit,advance:t.advance,credit:t.credit,damage:p.damage,notes:p.notes,status:'pending',applied:0,refunded:0};h.tenantId=null}
else if(action==='settle'){const tenant=state.tenants.find(t=>t.id===p.tenantId&&t.archived);if(!tenant)throw new Error('Archived tenant not found.');const s=tenant.settlement;if(s.status==='settled')throw new Error('This settlement is already recorded.');const available=s.deposit+s.advance+s.credit;if(p.applied>Math.max(0,s.outstanding)+s.damage||p.applied+p.refunded>available)throw new Error('Amounts exceed the recorded balance or held funds.');if(p.applied<s.applied||p.refunded<s.refunded)throw new Error('Recorded settlement totals cannot be reduced.');let increment=Math.min(p.applied,s.outstanding)-Math.min(s.applied,s.outstanding);tenantBills(tenant).forEach(b=>{const used=Math.min(increment,billTotal(b)-b.paid);b.paid+=used;increment-=used});Object.assign(s,p);s.status=p.applied+p.refunded===available?'settled':'pending'}
else throw new Error('Unknown action.');state.audit.push({action,date:new Date().toISOString(),by:user.name,recordId:p.houseId||p.tenantId||p.billId||p.paymentId});state.version++}catch(e){state=before;throw e}}
async function api(path,options={}){const r=await fetch('/api/'+path,{credentials:'same-origin',...options,headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...options.headers}});const result=await r.json();if(!r.ok)throw new Error(result.error||'The request could not be saved.');return result}
async function save(action,p){if(!navigator.onLine&&!demo)throw new Error('You are offline. Note the payment on paper and record it once the connection returns.');if(demo)applyDemo(action,p);else{let result;try{result=await api('action',{method:'POST',body:JSON.stringify({action,payload:p,version:state.version})})}catch(e){if(e.message.includes('refresh')||e.message.includes('Refresh')){state=(await api('state')).state;render()}throw e}state=result.state;lastPayment=result.payment||null}render();toast(demo?'Saved in this demo tab.':'Record saved.')}
function heading(eyebrow,title,subtitle,action=''){return '<div class="page-heading"><div><div class="eyebrow">'+eyebrow+'</div><h1>'+title+'</h1><p class="subtitle">'+subtitle+'</p></div>'+action+'</div>'}
function setChrome(route){document.querySelectorAll('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===route));$('#crumb').textContent=({houses:'Houses',payments:'Payments',reports:'Monthly reports',archive:'Tenant archive',settings:'Settings',login:'Sign in',family:'Family access'})[route]||'House details';$('#user-info').innerHTML=user?'<div class="user-card"><span class="user-circle">'+esc(user.name.slice(0,2).toUpperCase())+'</span><div><b>'+esc(user.name)+'</b><small>'+esc(user.role==='owner'?'Owner / Admin':user.role==='cashier'?'Cashier':'Viewer')+'</small></div></div>':'';$('#mode-notice').innerHTML=demo?'<div class="notice"><span><strong>Demo workspace.</strong> Fictional tenants · changes reset when this tab closes.</span><button data-action="connect">'+(liveAvailable?'Sign in to real records':'Live setup needed')+'</button></div>':''}
function render(){const parts=(location.hash.slice(1)||'houses').split('/'),route=parts[0];setChrome(route);if(!demo&&!user){renderLogin();return}if(route==='house'){renderHouse(parts[1]);return}if(route==='payments')renderPayments();else if(route==='reports')renderReports();else if(route==='archive')renderArchive();else if(route==='settings')renderSettings();else if(route==='family')renderFamily();else if(route==='login')renderLogin();else renderHouses()}
function renderHouses(){const occupied=state.houses.filter(activeTenant).length,overdue=state.houses.filter(h=>status(h).key==='overdue'),collected=state.payments.filter(p=>!p.voided&&p.date.startsWith(today().slice(0,7))).reduce((n,p)=>n+p.amount,0),outstanding=state.tenants.reduce((n,t)=>n+tenantBalance(t),0);$('#main').innerHTML=heading('YOUR RENTAL LEDGER','A place for every house.','Rent, utilities, and payments. All in one familiar place.',user.role==='owner'?button('＋ Add house','add-house','','primary'):'')+'<div class="stats"><div class="stat"><div class="stat-label">Occupied houses</div><div class="stat-value">'+occupied+' <small>/ '+state.houses.length+'</small></div><div class="stat-note">'+(state.houses.length-occupied)+' ready for a new tenant</div></div><div class="stat"><div class="stat-label">Collected this month</div><div class="stat-value">'+money(collected)+'</div><div class="stat-note">Confirmed payments only</div></div><div class="stat"><div class="stat-label">Outstanding balance</div><div class="stat-value warm">'+money(outstanding)+'</div><div class="stat-note">Across current and former tenants</div></div><div class="stat"><div class="stat-label">Overdue houses</div><div class="stat-value">'+overdue.length+' <small>houses</small></div><div class="stat-note">No late fees added</div></div></div>'+(overdue.length?'<div class="attention"><p><strong>'+overdue.length+' '+(overdue.length===1?'house needs':'houses need')+' a follow-up.</strong> Some payments are past their due date.</p><button data-action="filter-overdue">View overdue →</button></div>':'')+'<div class="toolbar"><div class="tabs">'+[['all','All houses',state.houses.length],['overdue','Overdue',overdue.length],['vacant','Vacant',state.houses.length-occupied]].map(([key,label,count])=>'<button class="tab '+(filter===key?'active':'')+'" data-filter="'+key+'">'+label+' <small>'+count+'</small></button>').join('')+'</div><div class="search-wrap"><span>⌕</span><input id="search" aria-label="Search house or tenant" placeholder="Find a house or tenant" value="'+esc(query)+'"></div></div><div class="houses-grid" id="house-grid"></div>';renderCards();$('#search').oninput=e=>{query=e.target.value;renderCards()}}
function renderCards(){const houses=state.houses.filter(h=>{const t=activeTenant(h);return(filter==='all'||status(h).key===filter)&&(h.label+' '+(t?.name||'')).toLowerCase().includes(query.toLowerCase())});$('#house-grid').innerHTML=houses.map(h=>{const t=activeTenant(h),s=status(h),bill=t&&tenantBills(t).filter(b=>billTotal(b)>b.paid)[0],due=bill?.due||(t&&nextDue(t.moveIn,Math.max(1,((Number(today().slice(0,4))-Number(t.moveIn.slice(0,4)))*12+Number(today().slice(5,7))-Number(t.moveIn.slice(5,7))))));return '<article class="house-card '+(!t?'vacant-card':'')+'"><div class="card-body"><div class="card-top"><div class="house-number"><span class="house-icon">'+houseSvg+'</span><div><h2>'+esc(h.label)+'</h2><small>Monthly rent '+money(h.rent)+'</small></div></div>'+badge(s)+'</div>'+(t?'<p class="tenant-name">'+esc(t.name)+'</p><p class="tenant-caption">Registered tenant · Mangungupahan</p><div class="card-financial"><div><label>Amount to pay</label><strong>'+money(tenantBalance(t))+'</strong></div><div><label>Due date</label><span class="due-text">'+shortDate(due)+'</span></div></div>':'<p class="vacant-message">Room for someone new.</p><p class="tenant-caption">No tenant assigned</p><div class="card-financial"><div><label>Monthly rent</label><strong>'+money(h.rent)+'</strong></div></div>')+'</div><div class="card-footer"><span>'+(t?(s.key==='paid'?'All recorded bills settled':'Rent + electricity + water'):'Tenant details start fresh')+'</span><button data-action="open-house" data-id="'+esc(h.id)+'">'+(t?'Open house':'View house')+' →</button></div></article>'}).join('')||'<div class="empty">No houses match your search.</div>'}
function renderHouse(id){const h=state.houses.find(h=>h.id===id);if(!h){location.hash='houses';return}const t=activeTenant(h);$('#main').innerHTML='<button class="back-link" data-action="back">← Back to houses</button>'+heading('HOUSE RECORD',esc(h.label),t?'One tenant. One ledger. A clear payment history.':'This house is ready for a new tenant.',badge(status(h)));if(!t){$('#main').innerHTML+='<div class="panel empty"><h3>A fresh start.</h3><p>Monthly rent: '+money(h.rent)+'<br>Add the registered tenant when they move in.</p><br>'+ (user.role==='owner'?button('＋ Assign tenant','tenant',id,'primary'):'Only the owner can assign a tenant.')+'</div>';return}const bills=tenantBills(t),payments=state.payments.filter(p=>p.tenantId===t.id).sort((a,b)=>b.recordedAt.localeCompare(a.recordedAt)),recent=bills.at(-1);$('#main').innerHTML+='<div class="detail-columns"><div><section class="panel"><div class="section-heading"><h2>'+esc(t.name)+'</h2>'+button('Print statement','statement',id)+'</div><dl class="detail-summary"><div><dt>Contact number</dt><dd>'+esc(t.contact)+'</dd></div><div><dt>Moved in</dt><dd>'+dateLabel(t.moveIn)+'</dd></div><div><dt>Monthly rent</dt><dd>'+money(h.rent)+'</dd></div><div><dt>Payment schedule</dt><dd>Every '+new Date(t.moveIn+'T12:00:00').getDate()+' of the month</dd></div></dl></section><section class="panel"><div class="balance-banner"><div><small>OUTSTANDING · KAILANGANG BAYARAN</small><strong>'+money(tenantBalance(t))+'</strong></div>'+(user.role!=='viewer'?button('Record payment','payment',id,'primary'):'')+'</div><div class="section-heading"><h2>Monthly bills</h2>'+(user.role==='owner'?button('＋ Create bill','bill',id):'')+'</div><div class="table-wrap"><table><thead><tr><th>Period / Due</th><th class="amount">Bill total</th><th class="amount">Remaining</th><th></th></tr></thead><tbody>'+bills.slice().reverse().map(b=>'<tr><td>'+esc(b.period)+'<br><small class="muted">'+dateLabel(b.due)+'</small></td><td class="amount">'+money(billTotal(b))+'</td><td class="amount">'+money(billTotal(b)-b.paid)+'</td><td>'+button('View','view-bill',b.id)+'</td></tr>').join('')+'</tbody></table></div>'+(!bills.length?'<div class="notice-block">No bills yet. Create the first monthly bill after entering meter readings.</div>':'')+'</section><section class="panel receipt-list"><h2>Payment history</h2>'+paymentTable(payments)+'</section></div><div><section class="panel"><h2>Latest bill breakdown</h2>'+(recent?'<div class="line-item"><span>Monthly rent</span><span>'+money(recent.rent)+'</span></div><div class="line-item"><span>Electricity<small>'+readingLabel(recent,'electric')+'</small></span><span>'+money(recent.electric)+'</span></div><div class="line-item"><span>Water<small>'+readingLabel(recent,'water')+'</small></span><span>'+money(recent.water)+'</span></div><div class="line-item"><span>Other charges</span><span>'+money(recent.other)+'</span></div><div class="line-item total"><span>Bill total</span><span>'+money(billTotal(recent))+'</span></div>':'<p class="notice-block">Add a bill to see the charges.</p>')+'</section><section class="panel"><h2>Held funds</h2><div class="line-item"><span>Security deposit</span><span>'+money(t.deposit)+'</span></div><div class="line-item"><span>Move-in advance</span><span>'+money(t.advance)+'</span></div><div class="line-item"><span>Payment credit</span><span>'+money(t.credit)+'</span></div><p class="notice-block">Advance policy: '+esc(t.advancePolicy)+'. Move-in advance stays separate until the owner confirms how it should be used.</p></section><section class="panel"><div class="section-heading"><h2>Tenant documents</h2>'+(user.role==='owner'?button('＋ Upload','upload',t.id):'')+'</div>'+t.documents.map(d=>'<div class="document-row"><span>'+esc(d.name)+'</span>'+'<div class="inline-actions">'+button('Open','document',d.id)+(user.role==='owner'?button('Remove','delete-document',d.id,'text'):'')+'</div></div>').join('')+(!t.documents.length?'<p class="notice-block">Valid IDs and the signed agreement belong here. Only the owner can upload or remove them.</p>':'')+(demo?'<small class="muted">Uploads are disabled for sample tenants.</small>':'')+'</section>'+(user.role==='owner'?'<div class="inline-actions">'+button('Change rates','rates',id)+button('Move-out checklist','archive',id,'danger')+'</div>':'')+'</div></div>'}
function readingLabel(b,type){if(b.mode!=='meter')return 'Manually entered';const r=b.readings;return esc(r[type+'Current'])+' − '+esc(r[type+'Previous'])+' × '+money(b[type+'Rate'])+(type==='electric'?' / kWh':' / m³')}
function paymentTable(payments){if(!payments.length)return '<p class="notice-block">No confirmed payments yet.</p>';return '<div class="table-wrap"><table><thead><tr><th>Receipt / Tenant</th><th>Date</th><th class="amount">Received</th><th></th></tr></thead><tbody>'+payments.map(p=>'<tr><td>'+esc(p.receipt)+'<br><small class="muted">'+esc(p.tenantName)+' · '+esc(p.houseLabel)+(p.voided?' · VOIDED':'')+'</small></td><td>'+shortDate(p.date)+'</td><td class="amount">'+money(p.amount)+'</td><td>'+button('Receipt','receipt',p.id)+(user.role==='owner'&&!p.voided?button('Correct','void',p.id,'text'):'')+'</td></tr>').join('')+'</tbody></table></div>'}
function renderPayments(){$('#main').innerHTML=heading('COLLECTIONS','Every payment, recorded.','Full payment or hulog—keep the amount actually received.',user.role!=='viewer'?button('＋ Record payment','choose-payment','','primary'):'')+'<div class="panel receipt-list">'+paymentTable(state.payments.slice().sort((a,b)=>b.recordedAt.localeCompare(a.recordedAt)))+'</div>'}
function renderReports(){const payments=state.payments.filter(p=>!p.voided&&p.date.startsWith(reportMonth)),total=payments.reduce((n,p)=>n+p.amount,0);$('#main').innerHTML=heading('MONTHLY COLLECTIONS','The month, on paper.','A record of money received. Deposits and move-in advances are shown separately.',button('↓ Download CSV','export','','primary'))+'<div class="toolbar"><div><input class="month-selector" aria-label="Report month" id="report-month" type="month" value="'+esc(reportMonth)+'"></div><p class="muted small">'+payments.length+' confirmed payments</p></div><div class="panel"><div class="eyebrow">TOTAL RECEIVED · '+esc(reportMonth)+'</div><div class="report-total">'+money(total)+'</div><p class="muted">Cash received toward bills and payment credit. This is not a profit report.</p></div><div class="panel"><h2>Collections by house</h2><div class="table-wrap"><table><thead><tr><th>House</th><th>Payments</th><th class="amount">Amount received</th><th class="amount">Unpaid bills</th></tr></thead><tbody>'+state.houses.map(h=>'<tr><td>'+esc(h.label)+'</td><td>'+payments.filter(p=>p.houseId===h.id).length+'</td><td class="amount">'+money(payments.filter(p=>p.houseId===h.id).reduce((n,p)=>n+p.amount,0))+'</td><td class="amount">'+money(state.tenants.filter(t=>t.houseId===h.id).reduce((n,t)=>n+tenantBalance(t),0))+'</td></tr>').join('')+'</tbody></table></div></div><div class="panel receipt-list"><h2>Payment ledger</h2>'+paymentTable(payments)+'</div>';$('#report-month').onchange=e=>{reportMonth=e.target.value;renderReports()}}
function renderArchive(){const archived=state.tenants.filter(t=>t.archived);$('#main').innerHTML=heading('FORMER TENANTS','A clean move-out.','Keep the payment trail while reviewing deposits, advances, and remaining bills.')+(archived.length?archived.map(t=>'<div class="panel archive-row"><div class="section-heading"><h3>'+esc(t.name)+' · '+esc(state.houses.find(h=>h.id===t.houseId)?.label||'')+'</h3>'+badge({key:t.settlement.status==='settled'?'paid':'due',label:t.settlement.status==='settled'?'Settled':'Settlement pending'})+'</div><p>Moved out '+dateLabel(t.moveOut)+' · Unpaid bills '+money(t.settlement.outstanding)+'<br>Deposit '+money(t.deposit)+' · Move-in advance '+money(t.advance)+' · Credit '+money(t.settlement.credit)+'<br>Applied '+money(t.settlement.applied)+' · Refunded '+money(t.settlement.refunded)+'<br>'+esc(t.settlement.notes)+'</p><br>'+(user.role==='owner'?button('Review settlement','settle',t.id):'')+button('Payment history','tenant-history',t.id)+'</div>').join(''):'<div class="empty"><h3>No archived tenants.</h3><p>Use a house’s move-out checklist when a tenant leaves.<br>The house becomes vacant; their earlier records stay here.</p></div>')}
function renderSettings(){$('#main').innerHTML=heading('WORKSPACE','Keep the rules simple.','The owner manages rates and corrections. The cashier confirms new payments.')+'<div class="panel"><h2>Billing defaults</h2><div class="setting-row"><div><strong>Electricity</strong><p>Default rate for new meter bills</p></div><strong>'+money(state.settings.electricRate)+' / kWh</strong></div><div class="setting-row"><div><strong>Water</strong><p>Default rate for new meter bills</p></div><strong>'+money(state.settings.waterRate)+' / m³</strong></div><div class="setting-row"><div><strong>Late fees</strong><p>Overdue balances carry forward without penalties</p></div><strong>None</strong></div><div class="notice-block">New rates apply to new bills. Saved bills keep their original rates and amounts.</div>'+(user.role==='owner'?button('Edit utility rates','rates','','primary'):'')+'</div><div class="panel"><h2>Receipt details</h2><div class="setting-row"><div><strong>'+esc(state.settings.name)+'</strong><p>'+esc(state.settings.address)+'</p></div>'+(user.role==='owner'?button('Edit','settings-info'):'')+'</div><p class="notice-block">Use 58 mm for your VOZY P50 or a full page for a formal copy. Select the printer in your laptop’s print dialog.</p></div><div class="panel"><h2>Family access</h2><div class="setting-row"><div><strong>Owner / Admin</strong><p>Houses, tenants, documents, meter bills, rates, corrections, and move-out settlements.</p></div><span class="badge paid">Full access</span></div><div class="setting-row"><div><strong>Cashier · Mom</strong><p>View the ledger, confirm new payments, print, and export monthly collections.</p></div><span class="badge partial">Collections</span></div>'+(demo?'<div class="notice-block">Test both roles below. These demo switches are not account authentication.</div><div class="inline-actions">'+button('Try Owner','demo-owner')+button('Try Cashier','demo-cashier')+button('Reset sample data','reset-demo')+'</div>':'<div class="notice-block">Approve a family member’s email before they create their login.</div>'+button('Manage family access','family')+'')+'</div><div class="panel"><h2>Recent changes</h2>'+(state.audit.slice(-12).reverse().map(a=>'<div class="line-item"><span>'+esc(a.action.replaceAll('_',' '))+'<small>'+esc(a.by)+'</small></span><span>'+dateLabel(a.date.slice(0,10))+'</span></div>').join('')||'<p class="notice-block">No changes recorded in this workspace yet.</p>')+'</div>'}

let familyMembers=[];
async function renderFamily(){if(user?.role!=='owner'){location.hash='houses';return}$('#main').innerHTML=heading('FAMILY ACCOUNTS','The right access for each person.','Approve an email, then ask them to create a login on this website.',button('＋ Approve family member','approve-family','','primary'))+'<div class="panel" id="family-list"><p class="notice-block">Loading approved accounts…</p></div>';try{if(demo){familyMembers=[{email:'approved-owner@example.invalid',name:'Owner',role:'owner',active:true}]}else familyMembers=(await api('members')).members;$('#family-list').innerHTML=familyMembers.map(m=>'<div class="setting-row"><div><strong>'+esc(m.name)+'</strong><p>'+esc(m.email)+' · '+esc(m.role)+(m.active?'':' · Access disabled')+'</p></div>'+(m.role==='owner'?badge({key:'paid',label:'Owner'}):button('Edit access','member-access',m.email))+'</div>').join('')}catch(e){$('#family-list').textContent=e.message}}
function openFamilyForm(member){modal(member?'Edit family access':'Approve family access','Only you can manage account access.',field('Family member name','name','text',member?.name||'','required maxlength="100"')+field('Email address','email','email',member?.email||'','required')+'<div class="field"><label for="f-role">Role</label><select name="role" id="f-role"><option value="cashier" '+(member?.role==='cashier'?'selected':'')+'>Cashier · Record and confirm payments</option><option value="viewer" '+(member?.role==='viewer'?'selected':'')+'>Viewer · View, print, and export</option></select></div><label class="check-label"><input type="checkbox" name="active" '+(!member||member.active?'checked':'')+'> Allow this family member to access the ledger</label>','Save access',async f=>{if(demo){toast('Account approval is available in the live workspace.');return}await api('members',{method:'POST',body:JSON.stringify({name:f.get('name'),email:f.get('email'),role:f.get('role'),active:f.get('active')==='on'})});renderFamily();toast('Family access updated. They can now create their login.')})}

function renderLogin(){$('#main').innerHTML='<div class="login-wrap panel"><div class="eyebrow">FAMILY ACCESS</div><h1>Welcome home.</h1><p class="subtitle">Sign in to your rental ledger.</p><br><form id="login-form">'+field('Email address','email','email','','required autocomplete="username"')+field('Password','password','password','','required autocomplete="current-password"')+'<div id="login-error" class="form-error" role="alert"></div><button class="btn primary" type="submit">Sign in</button> '+button('Create family login','signup')+'</form><p class="notice-block">Only approved family accounts can open real records. Use the email approved for your family role.</p></div>';$('#login-form').onsubmit=async e=>{e.preventDefault();if(!liveAvailable){$('#login-error').textContent='The live database is not configured yet. You can explore the demo.';return}const f=new FormData(e.target),b=e.submitter;b.disabled=true;try{const result=await api('login',{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password')})});user=result.user;state=result.state;demo=false;location.hash='houses';render()}catch(err){$('#login-error').textContent=err.message}finally{b.disabled=false}}}
function openTenant(id){const h=state.houses.find(h=>h.id===id);modal('Assign a tenant',h.label+' · Start with their current information.','<div class="form-grid">'+field('Full name','name','text','','required maxlength="100"')+field('Contact number','contact','tel','','required maxlength="30"')+field('Move-in date','moveIn','date',today(),'required')+cashField('Security deposit (₱)','deposit',h.rent)+cashField('Move-in advance (₱)','advance',h.rent)+'<div class="field"><label for="f-advancePolicy">Advance policy</label><select id="f-advancePolicy" name="advancePolicy"><option value="unconfirmed">Not yet confirmed</option><option value="first-month">For the first month</option><option value="last-month">Held for the last month</option></select></div></div><div class="info-box">The next due date is one month after move-in. Move-in advance is held separately; it will not automatically mark a bill paid.</div>','Assign tenant',async f=>save('tenant',{houseId:id,name:f.get('name').trim(),contact:f.get('contact').trim(),moveIn:f.get('moveIn'),deposit:peso(f.get('deposit')),advance:peso(f.get('advance')),advancePolicy:f.get('advancePolicy')}))}
function openBill(id){const h=state.houses.find(h=>h.id===id),t=activeTenant(h),bills=tenantBills(t),last=bills.at(-1),months=Math.max(1,(Number(today().slice(0,4))-Number(t.moveIn.slice(0,4)))*12+Number(today().slice(5,7))-Number(t.moveIn.slice(5,7))),due=last?nextDue(t.moveIn,(Number(last.due.slice(0,4))-Number(t.moveIn.slice(0,4)))*12+Number(last.due.slice(5,7))-Number(t.moveIn.slice(5,7))+1):nextDue(t.moveIn,months);modal('Create monthly bill',h.label+' · '+t.name,'<div class="form-grid">'+field('Billing month','period','month',due.slice(0,7),'required')+field('Due date','due','date',due,'required')+'</div><div class="field"><label for="bill-mode">Utility calculation</label><select name="mode" id="bill-mode"><option value="meter">Meter readings · Automatic</option><option value="manual">Enter amounts · Manual</option></select></div>'+cashField('Monthly rent (₱)','rent',h.rent)+'<div id="meter-fields" class="form-grid">'+field('Electricity · Previous (kWh)','electricPrevious','number',last?.readings?.electricCurrent||0,'min="0" step="0.001" required')+field('Electricity · Present (kWh)','electricCurrent','number','','min="0" step="0.001" required')+field('Water · Previous (m³)','waterPrevious','number',last?.readings?.waterCurrent||0,'min="0" step="0.001" required')+field('Water · Present (m³)','waterCurrent','number','','min="0" step="0.001" required')+'</div><div id="manual-fields" class="form-grid" hidden>'+cashField('Electricity amount (₱)','electric')+cashField('Water amount (₱)','water')+'</div>'+cashField('Other agreed charges (₱)','other')+'<div class="field"><label for="f-notes">Notes / charge description</label><textarea id="f-notes" name="notes" maxlength="500"></textarea></div><div class="info-box" id="bill-preview">Electricity '+money(state.settings.electricRate)+'/kWh · Water '+money(state.settings.waterRate)+'/m³. Previous unpaid bills stay separate and are added to the statement.</div>','Save bill',async f=>{const mode=f.get('mode');const readings=mode==='meter'?Object.fromEntries(['electricPrevious','electricCurrent','waterPrevious','waterCurrent'].map(k=>[k,requireNumber(f.get(k))])):{};await save('bill',{houseId:id,period:f.get('period'),due:f.get('due'),mode,readings,rent:peso(f.get('rent')),electric:peso(f.get('electric')),water:peso(f.get('water')),other:peso(f.get('other')),notes:f.get('notes')})});$('#bill-mode').onchange=e=>{$('#meter-fields').hidden=e.target.value==='manual';$('#manual-fields').hidden=e.target.value==='meter';$('#meter-fields').querySelectorAll('input').forEach(x=>{x.required=e.target.value==='meter';x.disabled=e.target.value==='manual'})}}
function openPayment(id){const h=state.houses.find(h=>h.id===id),t=activeTenant(h),balance=tenantBalance(t),requestId=crypto.randomUUID();modal('Record a payment',h.label+' · '+t.name,'<div class="balance-banner"><div><small>BEFORE THIS PAYMENT</small><strong>'+money(balance)+'</strong></div></div>'+cashField('Amount actually received (₱)','amount',balance)+field('Payment date','date','date',today(),'required max="'+today()+'"')+'<div class="field"><label for="f-notes">Notes (optional)</label><textarea name="notes" id="f-notes" maxlength="500" placeholder="Example: Partial payment received in cash"></textarea></div><div class="info-box">Payment goes to the oldest unpaid bill first. Any extra becomes payment credit for a future bill.</div><label class="check-label"><input type="checkbox" name="confirmed" required> I have received this money and checked the amount.</label>','Confirm payment',async f=>{await save('payment',{houseId:id,amount:peso(f.get('amount')),date:f.get('date'),notes:f.get('notes'),requestId});if(lastPayment)setTimeout(()=>openPrint('receipt',lastPayment.id),80)})}

function openBillCorrection(id){const b=state.bills.find(b=>b.id===id);modal('Correct a saved bill','Owner only · Previous values stay in the audit record.','<div class="form-grid">'+cashField('Rent (₱)','rent',b.rent)+(b.mode==='meter'?field('Electricity · Previous','electricPrevious','number',b.readings.electricPrevious,'min="0" step="0.001" required')+field('Electricity · Present','electricCurrent','number',b.readings.electricCurrent,'min="0" step="0.001" required')+field('Water · Previous','waterPrevious','number',b.readings.waterPrevious,'min="0" step="0.001" required')+field('Water · Present','waterCurrent','number',b.readings.waterCurrent,'min="0" step="0.001" required'):cashField('Electricity (₱)','electric',b.electric)+cashField('Water (₱)','water',b.water))+cashField('Other charges (₱)','other',b.other)+'</div><div class="field"><label for="f-reason">Reason for correction</label><textarea id="f-reason" name="reason" required maxlength="500"></textarea></div><div class="info-box">Uses the original bill’s utility rates. A corrected total cannot be less than money already applied.</div>','Save correction',async f=>save('bill_correction',{billId:id,mode:b.mode,rent:peso(f.get('rent')),electric:peso(f.get('electric')||0),water:peso(f.get('water')||0),other:peso(f.get('other')),readings:b.mode==='meter'?Object.fromEntries(['electricPrevious','electricCurrent','waterPrevious','waterCurrent'].map(k=>[k,requireNumber(f.get(k))])):{},notes:b.notes,reason:f.get('reason')}))}

function openRates(id){const h=state.houses.find(h=>h.id===id);modal('Change rates',h?h.label+' · Utility defaults apply to every house.':'Shared utility rates for every house.',(h?cashField('Monthly rent (₱)','rent',h.rent):'')+cashField('Electricity rate (₱ per kWh)','electricRate',state.settings.electricRate)+cashField('Water rate (₱ per m³)','waterRate',state.settings.waterRate)+'<div class="info-box">Only future bills use the new rates. Past and unpaid bills keep the rates used when they were created.</div><label class="check-label"><input type="checkbox" required> I checked these rates before saving.</label>','Save rates',async f=>save('rates',{houseId:id||null,...(h?{rent:peso(f.get('rent'))}:{}),electricRate:peso(f.get('electricRate')),waterRate:peso(f.get('waterRate'))}))}
function openArchive(id){const h=state.houses.find(h=>h.id===id),t=activeTenant(h);modal('Move-out checklist',t.name+' · '+h.label,field('Move-out date','date','date',today(),'required min="'+t.moveIn+'"')+'<div class="line-item"><span>Unpaid bills</span><span>'+money(tenantBalance(t))+'</span></div><div class="line-item"><span>Deposit + move-in advance + credit</span><span>'+money(t.deposit+t.advance+t.credit)+'</span></div><br>'+cashField('Agreed damage deductions (₱)','damage')+'<div class="field"><label for="f-notes">Settlement notes</label><textarea id="f-notes" name="notes" maxlength="500" placeholder="Note deductions, agreed refunds, or a pending settlement."></textarea></div><label class="check-label"><input type="checkbox" name="checklist" required> I reviewed rent, final utilities, property condition, deposit, and advance.</label><div class="info-box">This archives the tenant and frees the house. It does not delete their records or automatically apply or refund held funds.</div>','Archive tenant',async f=>{await save('archive',{houseId:id,date:f.get('date'),damage:peso(f.get('damage')),notes:f.get('notes'),checklist:true});location.hash='archive'})}
function openSettle(id){const t=state.tenants.find(t=>t.id===id),s=t.settlement;modal('Review held funds',t.name,'<div class="line-item"><span>Funds held at move-out</span><span>'+money(s.deposit+s.advance+s.credit)+'</span></div><div class="line-item"><span>Unpaid bills + agreed damages</span><span>'+money(s.outstanding+s.damage)+'</span></div><br>'+cashField('Total applied to dues / damages (₱)','applied',s.applied)+cashField('Total refunded to tenant (₱)','refunded',s.refunded)+'<div class="field"><label for="f-notes">Settlement notes</label><textarea name="notes" id="f-notes" required maxlength="500">'+esc(s.notes)+'</textarea></div><div class="info-box">Enter cumulative totals, not a new installment. Money still held remains pending. This is a settlement record; it does not create a cash payment receipt.</div>','Save settlement',async f=>save('settle',{tenantId:id,applied:peso(f.get('applied')),refunded:peso(f.get('refunded')),notes:f.get('notes')}))}
function printContent(type,id){if(type==='receipt'){const p=state.payments.find(p=>p.id===id),t=state.tenants.find(t=>t.id===p.tenantId);const rows=p.allocations.map(a=>{const b=a.billSnapshot||state.bills.find(b=>b.id===a.billId);return '<tr><td colspan="2"><b>'+esc(b?.period||'Bill')+'</b></td></tr>'+(b?'<tr><td>Rent '+money(b.rent)+'<br>Electricity '+money(b.electric)+'<br>Water '+money(b.water)+(b.other?'<br>Other '+money(b.other):'')+'</td><td></td></tr>':'')+'<tr><td>Applied to this bill</td><td class="amount">'+money(a.amount)+'</td></tr>'}).join('')+(p.credit?'<tr><td>Future payment credit</td><td class="amount">'+money(p.credit)+'</td></tr>':'');return printHead(p.voided?'VOIDED PAYMENT RECEIPT':'PAYMENT RECEIPT',p.receipt)+'<div class="print-meta"><div>Tenant: '+esc(p.tenantName)+'<br>House: '+esc(p.houseLabel)+'</div><div>Paid: '+dateLabel(p.date)+'<br>Recorded by: '+esc(p.recordedBy)+'</div></div><table><thead><tr><th>Payment applied to</th><th class="amount">Amount</th></tr></thead><tbody>'+rows+'</tbody></table><div class="print-total">Amount received: '+money(p.amount)+'</div><p>Balance after this payment: '+money(p.balanceAfter??tenantBalance(t))+'</p><div class="print-foot">'+(p.voided?'Voided: '+esc(p.voidReason):'Payment confirmed. Thank you.')+'<br>'+esc(p.notes||'')+'<br>Printed '+dateLabel(today())+' · Internal payment record<br>Reprints use the same receipt number.</div>'}const h=state.houses.find(h=>h.id===id),t=activeTenant(h),bills=tenantBills(t).filter(b=>billTotal(b)>b.paid);return printHead('BILLING STATEMENT','Statement · '+today())+'<div class="print-meta"><div>Tenant: '+esc(t.name)+'<br>House: '+esc(h.label)+'</div><div>Contact: '+esc(t.contact)+'</div></div><table><thead><tr><th>Charges</th><th class="amount">Amount</th></tr></thead><tbody>'+bills.map(b=>'<tr><td colspan="2"><b>'+esc(b.period)+' · Due '+dateLabel(b.due)+'</b></td></tr><tr><td>Monthly rent</td><td class="amount">'+money(b.rent)+'</td></tr><tr><td>Electricity<br>'+readingLabel(b,'electric')+'</td><td class="amount">'+money(b.electric)+'</td></tr><tr><td>Water<br>'+readingLabel(b,'water')+'</td><td class="amount">'+money(b.water)+'</td></tr>'+(b.other?'<tr><td>Other agreed charges</td><td class="amount">'+money(b.other)+'</td></tr>':'')+(b.paid?'<tr><td>Payments / credits applied</td><td class="amount">−'+money(b.paid)+'</td></tr>':'')).join('')+'</tbody></table><div class="print-total">Total to pay: '+money(tenantBalance(t))+'</div><div class="print-foot">This is an unpaid billing statement.<br>It is not proof of payment.<br>Previous unpaid balances are included once.<br>No late fees.<br>Prepared '+dateLabel(today())+'</div>'}
function printHead(title,reference){return '<div class="print-sheet"><div class="print-head"><h1>'+esc(state.settings.name)+'</h1><p>'+esc(state.settings.address)+'</p><h2>'+title+'</h2><p>'+esc(reference)+'</p>'+(demo?'<p>DEMO · SAMPLE DATA</p>':'')+'</div>'}
function openPrint(type,id){modal(type==='receipt'?'Payment receipt':'Billing statement',type==='receipt'?'A record of money received.':'Bring this to the tenant before they pay.','<div class="field"><label for="print-format">Paper format</label><select name="format" id="print-format"><option value="thermal">58 mm · VOZY P50</option><option value="full">Full page · Formal copy</option></select></div><div class="info-box">Use your laptop connected through USB. In the print dialog, select your printer, correct paper size, and turn off browser headers and footers. You can also save as PDF.</div>','Print',async f=>{document.body.classList.toggle('thermal',f.get('format')==='thermal');$('#print-area').innerHTML=printContent(type,id)+'</div>';let style=$('#print-page-size');if(!style){style=document.createElement('style');style.id='print-page-size';document.head.append(style)}style.textContent=f.get('format')==='thermal'?'@media print{@page{size:58mm 220mm;margin:5mm}}':'@media print{@page{size:A4;margin:15mm}}';window.print()})}
function exportCsv(){const items=state.payments.filter(p=>p.date.startsWith(reportMonth)),cell=v=>'"'+String(v??'').replace(/^[=+\-@\t\r]/,"'$&").replaceAll('"','""')+'"',rows=[['Receipt','Payment date','House','Tenant','Amount received PHP','New credit PHP','Recorded by','Status','Notes'],...items.map(p=>[p.receipt,p.date,p.houseLabel,p.tenantName,(p.amount/100).toFixed(2),(p.credit/100).toFixed(2),p.recordedBy,p.voided?'VOIDED':'Confirmed',p.notes||''])];const blob=new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='paupahan-payments-'+reportMonth+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Monthly payment report downloaded.')}
async function handleAction(action,id){if(action==='open-house'){location.hash='house/'+id;return}if(action==='back'){location.hash='houses';return}if(action==='filter-overdue'){filter='overdue';renderHouses();return}if(action==='tenant'){openTenant(id);return}if(action==='bill'){openBill(id);return}if(action==='payment'){openPayment(id);return}if(action==='rates'){openRates(id);return}if(action==='archive'){openArchive(id);return}if(action==='settle'){openSettle(id);return}if(action==='statement'||action==='receipt'){openPrint(action,id);return}if(action==='export'){exportCsv();return}if(action==='family'){location.hash='family';return}if(action==='approve-family'){openFamilyForm();return}if(action==='member-access'){const member=familyMembers.find(m=>m.email===id);openFamilyForm(member);return}if(action==='signup'){modal('Create your family login','Use the email approved for your family role.',field('Email address','email','email','','required autocomplete="username"')+field('New password','password','password','','required minlength="10" autocomplete="new-password"')+field('Confirm password','confirm','password','','required minlength="10" autocomplete="new-password"')+'<div class="info-box">Use the email approved for your family role.</div>','Create login',async f=>{if(f.get('password')!==f.get('confirm'))throw new Error('Passwords do not match.');const r=await api('signup',{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password')})});setTimeout(()=>modal('Check your email','Finish account confirmation.', '<p class="notice-block">'+esc(r.message)+'</p>',null),80)});return}if(action==='connect'){if(liveAvailable){demo=false;user=null;location.hash='login';render()}else modal('Live workspace setup','The interface is ready; live records require the backend.','<div class="info-box">Connect an active Supabase project, apply the database schema, and configure the Python API. Demo changes stay in this tab. Do not enter real tenant IDs here.</div>',null);return}if(action==='demo-owner'||action==='demo-cashier'){if($('#modal').open)$('#modal').close();if(!demo)state=sampleState();demo=true;user={name:action==='demo-owner'?'Owner':'Mom',role:action==='demo-owner'?'owner':'cashier'};location.hash='houses';render();return}if(action==='reset-demo'){state=sampleState();render();toast('Sample data reset.');return}if(action==='add-house'){modal('Add a house','A separate record for another rental unit.',field('House name / number','label','text','House '+String(state.houses.length+1).padStart(2,'0'),'required maxlength="60"')+cashField('Monthly rent (₱)','rent',400000),'Add house',async f=>save('house',{label:f.get('label').trim(),rent:peso(f.get('rent'))}));return}if(action==='choose-payment'){modal('Choose a house','Which tenant paid today?','<div class="field"><label for="payment-house">House / Tenant</label><select id="payment-house" name="houseId">'+state.houses.filter(activeTenant).map(h=>'<option value="'+esc(h.id)+'">'+esc(h.label)+' · '+esc(activeTenant(h).name)+'</option>').join('')+'</select></div>','Continue',async f=>setTimeout(()=>openPayment(f.get('houseId')),80));return}if(action==='void'){modal('Correct a payment','The original receipt is kept and marked void.','<div class="field"><label for="f-reason">Reason for correction</label><textarea name="reason" id="f-reason" required maxlength="500" placeholder="Describe the mistake. Record the corrected payment separately."></textarea></div><label class="check-label"><input type="checkbox" required> I reviewed the original receipt and want to reverse it.</label>','Void original payment',async f=>save('void',{paymentId:id,reason:f.get('reason')}));return}if(action==='view-bill'){const b=state.bills.find(b=>b.id===id);modal('Bill · '+b.period,'Due '+dateLabel(b.due),'<div class="line-item"><span>Rent</span><span>'+money(b.rent)+'</span></div><div class="line-item"><span>Electricity<small>'+readingLabel(b,'electric')+'</small></span><span>'+money(b.electric)+'</span></div><div class="line-item"><span>Water<small>'+readingLabel(b,'water')+'</small></span><span>'+money(b.water)+'</span></div><div class="line-item"><span>Other charges</span><span>'+money(b.other)+'</span></div><div class="line-item total"><span>Bill total</span><span>'+money(billTotal(b))+'</span></div><div class="line-item"><span>Already applied</span><span>'+money(b.paid)+'</span></div><div class="line-item"><span>Remaining</span><span>'+money(billTotal(b)-b.paid)+'</span></div><p class="notice-block">'+esc(b.notes)+'</p>'+(user.role==='owner'?button('Correct this bill','correct-bill',b.id):''),null);return}if(action==='correct-bill'){if($('#modal').open)$('#modal').close();openBillCorrection(id);return}if(action==='tenant-history'){const t=state.tenants.find(t=>t.id===id);modal('Payment history',t.name,paymentTable(state.payments.filter(p=>p.tenantId===id)),null);return}if(action==='settings-info'){modal('Receipt details','These details appear on future printouts.',field('Name on receipt','name','text',state.settings.name,'required maxlength="100"')+field('Property address','address','text',state.settings.address,'required maxlength="200"'),'Save details',async f=>save('settings',{name:f.get('name').trim(),address:f.get('address').trim()}));return}if(action==='upload'){if(demo){toast('Private uploads require a live account.');return}modal('Upload tenant document','Private · Visible to approved family accounts.','<div class="field"><label for="f-document">PDF, JPG, or PNG (up to 3 MB)</label><input type="file" name="file" id="f-document" accept=".pdf,.jpg,.jpeg,.png" required></div>','Upload',async f=>{const file=f.get('file');if(file.size>3*1024*1024)throw new Error('Maximum file size is 3 MB.');f.append('tenantId',id);await api('documents',{method:'POST',body:f});const r=await api('state');state=r.state;render();toast('Private document saved.')});return}if(action==='delete-document'){if(demo)return;modal('Remove document','The payment history will be kept.','<p class="notice-block">This permanently removes the selected uploaded file.</p><label class="check-label"><input type="checkbox" required> I checked the file and want to remove it.</label>','Remove file',async()=>{await api('documents/'+encodeURIComponent(id),{method:'DELETE'});state=(await api('state')).state;render();toast('Document removed.')});return}if(action==='document'){if(!demo){const r=await api('documents/'+encodeURIComponent(id));window.open(r.url,'_blank','noopener')}return}if(action==='logout'){await api('logout',{method:'POST'});user=null;demo=false;location.hash='login';render();return}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){handleAction(el.dataset.action,el.dataset.id||'').catch(err=>toast(err.message));return}const tab=e.target.closest('[data-filter]');if(tab){filter=tab.dataset.filter;renderHouses()}});
$('#account-button').onclick=()=>modal('Your workspace',demo?'Demo role · Not a real login.':user?.name||'Not signed in',demo?'<div class="inline-actions">'+button('Try Owner','demo-owner')+button('Try Cashier','demo-cashier')+'</div>':'<p class="notice-block">'+esc(user?.role||'')+'</p>'+button('Sign out','logout'),null);
window.addEventListener('hashchange',()=>{if($('#modal').open)$('#modal').close();render();window.scrollTo(0,0)});
$('#today').textContent=new Date().toLocaleDateString('en-PH',{weekday:'short',month:'short',day:'numeric',year:'numeric',timeZone:'Asia/Manila'});
async function init(){if(location.protocol==='file:'||String(location.hostname||'').endsWith('.chatgpt.site')){render();return}$('#main').innerHTML='<div class="empty"><h3>Opening your family workspace…</h3></div>';try{config=await api('config');liveAvailable=Boolean(config.configured);if(liveAvailable){try{const r=await api('state');state=r.state;user=r.user;demo=false;render()}catch{demo=false;user=null;location.hash='login';render()}}else render()}catch{demo=false;user=null;$('#mode-notice').innerHTML='';$('#main').innerHTML='<div class="empty"><h3>Unable to connect.</h3><p>Your records have not changed. Reload to try again.</p></div>'}}
init();
